'use strict';
const RESEARCH_FIELDS=['seed','intent','group','page','keywords','reason'];
let studioTab='rsa',rsaRotation=0,rsaExpanded=true;
function cleanStudio(value){const result={};if(!value||typeof value!=='object')return result;for(const b of BUSINESSES){const x=value[b.id];if(!x||typeof x!=='object')continue;const r={headlines:[],descriptions:[],paths:['',''],url:typeof x.url==='string'?x.url.slice(0,2000):'',answers:{},negative:{text:'',match:'broad',scope:'group'},research:{}};for(const [key,max,pins]of [['headlines',15,3],['descriptions',4,2]])for(let i=0;i<max;i++){const a=x[key]?.[i];r[key].push({text:typeof a?.text==='string'?a.text.slice(0,1000):'',pin:Number.isInteger(a?.pin)&&a.pin>=0&&a.pin<=pins?a.pin:0});}for(let i=0;i<2;i++)if(typeof x.paths?.[i]==='string')r.paths[i]=x.paths[i].slice(0,100);for(let i=0;i<8;i++)if(['keep','block','investigate'].includes(x.answers?.[i]))r.answers[i]=x.answers[i];if(typeof x.negative?.text==='string')r.negative.text=x.negative.text.slice(0,200);if(['broad','phrase','exact'].includes(x.negative?.match))r.negative.match=x.negative.match;if(['account','campaign','group'].includes(x.negative?.scope))r.negative.scope=x.negative.scope;for(const f of RESEARCH_FIELDS)if(typeof x.research?.[f]==='string')r.research[f]=x.research[f].slice(0,5000);result[b.id]=r;}return result;}
function studioRecord(){if(!state.studio[state.business]){const b=biz(),old=state.drafts[state.business]||{};state.studio[state.business]={headlines:Array.from({length:15},(_,i)=>({text:i<3?(old['h'+i]??[b.offer[1],b.benefit[1],'Check Details Online'][i]):'',pin:0})),descriptions:Array.from({length:4},(_,i)=>({text:i<2?(old['d'+i]??[b.desc[1],'Visit our website to review details and choose your next step.'][i]):'',pin:0})),paths:['',''],url:'https://'+b.domain+'/',answers:{},negative:{text:state.business==='shop'?'free':'jobs',match:'broad',scope:'group'},research:{}};}return state.studio[state.business];}
function rsaLength(text){return [...String(text)].reduce((n,c)=>n+(/[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Hangul}\uFF01-\uFF60\uFFE0-\uFFE6]/u.test(c)?2:1),0);}
function reviewRSA(r){const errors=[],warnings=[];const h=r.headlines.filter(a=>a.text.trim()),d=r.descriptions.filter(a=>a.text.trim());if(h.length<3)errors.push(U('Kam az kam 3 headlines likho.','Write at least three headlines.'));if(d.length<2)errors.push(U('Kam az kam 2 descriptions likho.','Write at least two descriptions.'));for(const [name,items,limit]of [['H',r.headlines,30],['D',r.descriptions,90]])items.forEach((a,i)=>{if(rsaLength(a.text)>limit)errors.push(`${name}${i+1}: ${rsaLength(a.text)}/${limit}`);if(a.pin&&!a.text.trim())warnings.push(`${name}${i+1}: ${U('pin hai lekin text blank hai','pinned but blank')}`);});r.paths.forEach((p,i)=>{if(rsaLength(p)>15)errors.push(`Path ${i+1}: ${rsaLength(p)}/15`);});for(const [label,items]of [['Headlines',h],['Descriptions',d]])if(new Set(items.map(a=>a.text.trim().toLowerCase().replace(/\s+/g,' '))).size<items.length)warnings.push(label+': '+U('duplicate text review karo','review duplicate text'));try{const u=new URL(r.url);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error();if(u.hostname.endsWith('.example'))warnings.push(U('.example fictional destination hai; live ad ke liye usable page chahiye.','.example is fictional; a live ad requires a usable destination.'));}catch{errors.push(U('Valid http/https final URL likho, credentials ke baghair.','Enter a valid http/https final URL without credentials.'));}if(h.some(a=>a.pin===3)||d.some(a=>a.pin===2))warnings.push(U('H3 / D2 har format mein show honay ki guarantee nahi; essential message yahan akela mat rakho.','H3 / D2 are not guaranteed in every format; do not rely on them alone for essential messaging.'));if([...h,...d].some(a=>a.pin))warnings.push(U('Pinning combinations restrict karti hai. Har pin ki specific reason honi chahiye.','Pinning restricts combinations. Have a specific reason for each pin.'));return{errors,warnings,headlines:h.length,descriptions:d.length};}
function sampleRSA(items,positions,offset){const used=new Set();return Array.from({length:positions},(_,i)=>{const slot=i+1,pinned=items.map((a,n)=>({...a,n})).filter(a=>a.text.trim()&&a.pin===slot);const pool=pinned.length?pinned:items.map((a,n)=>({...a,n})).filter(a=>a.text.trim()&&!a.pin);const choices=pool.filter(a=>!used.has(a.n));if(!choices.length)return null;const a=choices[(offset+i)%choices.length];used.add(a.n);return a;});}
function rsaPreview(){const r=studioRecord(),h=sampleRSA(r.headlines,rsaExpanded?3:2,rsaRotation),d=sampleRSA(r.descriptions,rsaExpanded?2:1,rsaRotation);let host;try{host=new URL(r.url).hostname;}catch{host=U('Destination URL review karo','Review destination URL');}return `<div class="simulation-label">ILLUSTRATIVE SAMPLE · NOT GOOGLE UI OR A SERVING PREDICTION</div><div class="campaign-preview" style="margin-top:18px;overflow-wrap:anywhere"><small>Sponsored · ${esc(t(biz().name))}</small><p>${esc(host)}${r.paths.filter(Boolean).map(p=>' › '+esc(p)).join('')}</p><h3>${h.map((a,i)=>a?esc(a.text):`[${U('Is slot ke liye asset nahi','No asset for slot')} H${i+1}]`).join(' | ')}</h3><p>${d.map((a,i)=>a?esc(a.text):`[${U('Asset missing','Asset missing')} D${i+1}]`).join(' ')}</p></div><p>${U('Ye sirf selected sample hai. Real layout, truncation, enhanced flexibility aur serving vary kar saktay hain. Missing slot ka matlab is sample mein pin/unpinned choices insufficient hain; Google eligibility ka verdict nahi.','This is one selected sample. Actual layout, truncation, enhanced flexibility and serving can differ. A missing slot means this sample has insufficient eligible pin/unpinned choices, not a Google eligibility verdict.')}</p>`;}
function studioPage(){return `${heading('SEARCH ADS · CREATIVE & KEYWORD WORKSHOP',U('Sahi words. Relevant message.','The right words. A relevant message.'),U('Full RSA practice aur keyword planning; apne business ke drafts alag save karo.','Full RSA practice and keyword planning; drafts save separately by business.'))}<div class="note">${U('Teaching studio, real Google editor nahi. Ads publish nahi hoti. Google matching, Ad Strength, approval aur results ki prediction nahi hoti.','A teaching studio, not the Google editor. No ads are published. Google matching, Ad Strength, approval and results are not predicted.')}</div><div class="section-heading" style="margin-top:22px"><span class="tag">${esc(t(biz().name))}</span><select class="lang" id="studio-business" aria-label="Studio business">${BUSINESSES.map(b=>`<option value="${b.id}" ${b.id===state.business?'selected':''}>${esc(t(b.name))}</option>`).join('')}</select></div><div class="tabs"><button data-studio-tab="rsa" class="${studioTab==='rsa'?'active':''}">RSA · 15 headlines / 4 descriptions</button><button data-studio-tab="keywords" class="${studioTab==='keywords'?'active':''}">${U('Keywords & negatives','Keywords & negatives')}</button></div>${studioTab==='rsa'?fullRSAPage():keywordWorkshop()}${footer()}`;}
function rsaAssetFields(key,limit,maxPin){const r=studioRecord();return r[key].map((a,i)=>`<div class="rsa-asset"><label class="field">${key==='headlines'?'Headline':'Description'} ${i+1}${key==='headlines'?`<input data-rsa-text="${key}/${i}" value="${esc(a.text)}" maxlength="1000">`:`<textarea data-rsa-text="${key}/${i}" maxlength="1000" rows="2">${esc(a.text)}</textarea>`}<small id="rsa-count-${key}-${i}" ${rsaLength(a.text)>limit?'style="color:#a14c3e"':''}>${rsaLength(a.text)}/${limit}</small></label><label class="field">${U('Position pin','Position pin')}<select data-rsa-pin="${key}/${i}">${Array.from({length:maxPin+1},(_,n)=>`<option value="${n}" ${a.pin===n?'selected':''}>${n?(key==='headlines'?'H':'D')+n:U('Unpinned','Unpinned')}</option>`).join('')}</select></label></div>`).join('');}
function fullRSAPage(){const r=studioRecord();return `<div class="journey-layout rsa-layout"><section class="card"><h2>${U('Apna full responsive ad likho.','Write your full responsive ad.')}</h2><button class="btn light" data-go="screens/12">${U('Asli RSA editor dekho','See the original RSA editor')} →</button><p>${U('3–15 headlines; 2–4 descriptions. English/Roman Urdu counts live dikhte hain; double-width CJK ko 2 count karte hain. Other scripts, emoji aur exact validation Google editor mein verify karo.','Use 3–15 headlines and 2–4 descriptions. Counts update live; double-width CJK characters count as two. Verify other scripts, emoji and exact validation in Google’s editor.')}</p><label class="field">Final URL<input id="rsa-url" type="url" maxlength="2000" value="${esc(r.url)}"></label><div class="form-grid">${r.paths.map((p,i)=>`<label class="field">Display path ${i+1}<input data-rsa-path="${i}" maxlength="100" value="${esc(p)}"><small id="rsa-path-count-${i}">${rsaLength(p)}/15</small></label>`).join('')}</div><p class="screen-credit">${U('Display paths destination change nahi kartay. Advanced draft pehli dafa basic draft ki copy se start hota hai; dono baad mein separately save hotay hain.','Display paths do not change the destination. The advanced draft starts with a copy of your basic draft; they save separately afterward.')}</p><details open><summary>${U('Headlines · max 30 per asset','Headlines · max 30 per asset')}</summary>${rsaAssetFields('headlines',30,3)}</details><details open style="margin-top:20px"><summary>${U('Descriptions · max 90 per asset','Descriptions · max 90 per asset')}</summary>${rsaAssetFields('descriptions',90,2)}</details><small id="rsa-save" role="status">${U('Autosaved in this browser','Autosaved in this browser')}</small><div class="action-row"><button class="btn" id="rsa-review">${U('Draft review karo','Review draft')}</button><button class="btn light" id="rsa-export">${U('Full draft download','Download full draft')}</button></div><div id="rsa-feedback" aria-live="polite"></div></section><aside><div class="card"><div id="rsa-preview">${rsaPreview()}</div><div class="action-row"><button class="btn light" id="rsa-rotate">${U('Doosra combination','Another combination')}</button></div><label class="sim-check" style="margin-top:15px"><input type="checkbox" id="rsa-expanded" ${rsaExpanded?'checked':''}>${U('Optional H3 aur D2 sample mein dikhao','Include optional H3 and D2 in the sample')}</label></div><div class="card" style="margin-top:22px"><h3>${U('Pin samajh kar lagao','Pin with a reason')}</h3><p>${U('Same position par multiple pinned assets alternatives hain; sab ek saath nahi aatay. Pinned asset doosri position par rotate nahi hota. Essential text ke liye H1/H2/D1 ki official guidance parho; H3/D2 ko guaranteed mat samjho.','Multiple assets pinned to one position are alternatives, not simultaneous slots. Pinned text does not rotate to another position. Review official H1/H2/D1 guidance for required messaging; do not assume H3/D2 are guaranteed.')}</p>${sourceLinks(['rsa','creative'])}</div></aside></div>`;}
function negativeTokens(text){return String(text).normalize('NFKC').toLowerCase().match(/[\p{L}\p{N}]+/gu)||[];}
function negativeMatch(query,text,match){const q=negativeTokens(query),n=negativeTokens(text);if(!n.length||!['broad','phrase','exact'].includes(match))return false;if(match==='broad')return n.every(w=>q.includes(w));if(match==='exact')return q.length===n.length&&q.every((w,i)=>w===n[i]);return q.some((_,i)=>n.every((w,j)=>q[i+j]===w));}
function negativeFixtures(){const b=state.business;return b==='shop'?[
{q:'buy running shoes free delivery',campaign:'nonbrand',group:'main',useful:true},{q:'running shoes training',campaign:'nonbrand',group:'main',useful:false},{q:'walking shoes free delivery',campaign:'nonbrand',group:'other',useful:true},{q:'Stride running shoes free delivery',campaign:'brand',group:'main',useful:true},{q:'running shoe trainer job',campaign:'nonbrand',group:'main',useful:false}]:b==='b2b'?[
{q:'accounting jobs Karachi',campaign:'nonbrand',group:'main',useful:false},{q:'bookkeeping services Karachi',campaign:'nonbrand',group:'main',useful:true},{q:'payroll services Karachi',campaign:'nonbrand',group:'other',useful:true},{q:'LedgerPro bookkeeping',campaign:'brand',group:'main',useful:true},{q:'accounting job Karachi',campaign:'nonbrand',group:'main',useful:false}]:[
{q:'ac repair jobs Lahore',campaign:'nonbrand',group:'main',useful:false},{q:'ac repair Lahore',campaign:'nonbrand',group:'main',useful:true},{q:'ac installation Lahore',campaign:'nonbrand',group:'other',useful:true},{q:'CoolCare ac repair',campaign:'brand',group:'main',useful:true},{q:'ac repair job Lahore',campaign:'nonbrand',group:'main',useful:false}];}
function negativeImpact(f,rule){const scope=rule.scope==='account'||rule.scope==='campaign'&&f.campaign==='nonbrand'||rule.scope==='group'&&f.campaign==='nonbrand'&&f.group==='main';return Boolean(scope&&negativeMatch(f.q,rule.text,rule.match));}
function negativeResult(){const n=studioRecord().negative,rows=negativeFixtures(),conflicts=rows.filter(f=>f.useful&&negativeImpact(f,n));return `<div class="feedback ${conflicts.length?'error':''}">${U('Is fixture mein useful-query conflicts','Useful-query conflicts in this fixture')}: ${conflicts.length}. ${U('0 ka matlab poora account safe certify nahi hua.','Zero does not certify the whole account as safe.')}</div><div style="overflow:auto"><table class="data-table"><thead><tr><th>Query · fictional intent</th><th>Context</th><th>${U('Result','Result')}</th></tr></thead><tbody>${rows.map(f=>`<tr><td>${esc(f.q)}<br><small>${f.useful?U('Useful in this example','Useful in this example'):U('Unwanted intent','Unwanted intent')}</small></td><td>${f.campaign} / ${f.group}</td><td>${negativeImpact(f,n)?U('BLOCKED','BLOCKED'):U('Is negative se block nahi','Not blocked by this negative')}</td></tr>`).join('')}</tbody></table></div>`;}
function keywordSyntax(text){const result={broad:0,phrase:0,exact:0,errors:[],duplicates:[]},seen=new Set();String(text).split(/\r?\n/).forEach((line,i)=>{let s=line.trim();if(!s)return;if(/^[+−-]/.test(s)||/[“”]/.test(s)){result.errors.push(i+1);return;}let type='broad';if(s.startsWith('[')&&s.endsWith(']')){type='exact';s=s.slice(1,-1).trim();}else if(s.startsWith('"')&&s.endsWith('"')){type='phrase';s=s.slice(1,-1).trim();}else if(/[\[\]"]/.test(s)){result.errors.push(i+1);return;}if(!s||/[\[\]"]/.test(s)){result.errors.push(i+1);return;}const k=type+'/'+s.toLowerCase().replace(/\s+/g,' ');if(seen.has(k))result.duplicates.push(i+1);seen.add(k);result[type]++;});return result;}
function studioQueries(){const b=biz();return [...queries(),{term:b.name[1]+' '+b.customer[1],clicks:10,cost:10*b.cpc,out:1,answer:'keep',why:P('Brand aur offer relevant hain. Brand vs non-brand reporting alag dekho; cheap brand traffic ko non-brand uplift ki proof mat samjho.','Brand and offer fit. Separate brand/non-brand reporting; cheap brand traffic does not prove non-brand uplift.')},{term:state.business==='shop'?'running shoes wholesale bulk':state.business==='b2b'?'remote bookkeeping overseas company':'AC repair outside Lahore',clicks:4,cost:4*b.cpc,out:0,answer:'investigate',why:P('Wholesale, overseas ya coverage capability brief mein establish nahi. Business fit aur evidence confirm karo; blanket negative assume mat karo.','Wholesale, overseas or coverage capability is not established. Confirm business fit before making a blanket exclusion.')}];}
function studioQueryScore(){const answers=state.studio[state.business]?.answers||{};return studioQueries().filter((q,i)=>answers[i]===q.answer).length;}
function syntaxResult(){const x=keywordSyntax(studioRecord().research.keywords||'');return `${U('Draft syntax','Draft syntax')}: ${x.exact} exact · ${x.phrase} phrase · ${x.broad} broad. ${x.errors.length?U('Malformed lines: ','Malformed lines: ')+x.errors.join(', '):''} ${x.duplicates.length?U('Duplicate lines: ','Duplicate lines: ')+x.duplicates.join(', '):''}<br>${U('Ye syntax check hai; eligibility, volume ya Google matching ki prediction nahi.','Syntax only; not a prediction of eligibility, volume or Google matching.')}`;}
function keywordWorkshop(){const r=studioRecord(),n=r.negative;return `<section class="card"><h2>${U('01 · Research ko business se joro','01 · Connect research to the business')}</h2><button class="btn light" data-go="screens/5">${U('Original Keyword Planner screens dekho','See original Keyword Planner screens')} →</button><p>${U('Customer ki language se seed terms lo. Keyword Planner mein location/language/date context ke saath estimates verify karo. Yahan live volumes ya CPC research fetch nahi hoti; neeche query numbers fictional hain.','Start with customer language. Verify Planner estimates in location/language/date context. This app fetches no live volume or CPC research; the query numbers below are fictional.')}</p><div class="form-grid">${[
['seed',P('Customer ke seed terms','Customer seed terms')],['intent',P('Need / intent / offer fit','Need / intent / offer fit')],['group',P('Focused ad group','Focused ad group')],['page',P('Matching landing page','Matching landing page')],['keywords',P('Keyword list · one per line','Keyword list · one per line')],['reason',P('Match choice aur review plan ki reason','Reason for match choice and review plan')]
].map(([f,label])=>`<label class="field">${esc(t(label))}<textarea data-research="${f}" maxlength="5000" rows="3">${esc(r.research[f]||'')}</textarea></label>`).join('')}</div><div class="formula" id="keyword-syntax">${syntaxResult()}</div><div class="cards"><div class="example"><b>[exact match]</b><p>${U('Same meaning/intent aur close variants possible; sirf identical string nahi.','Same meaning/intent and close variants can be eligible, not just identical text.')}</p></div><div class="example"><b>"phrase match"</b><p>${U('Meaning matters; order jab meaning badlay to important ho sakta hai. Sirf literal substring engine nahi.','Meaning matters; order can matter when it changes meaning. This is not just literal substring matching.')}</p></div><div class="example"><b>broad match</b><p>${U('Related searches tak wider reach ho sakti hai. Measurement, bidding aur real search terms ka review saath chahiye.','May reach more related searches. Review measurement, bidding and actual search terms together.')}</p></div></div>${sourceLinks(['match','terms'])}</section><section class="card" style="margin-top:22px"><h2>${U('02 · Negative se useful traffic to nahi ruk rahi?','02 · Is a negative blocking useful traffic?')}</h2><p>${U('Simplified literal-word exercise: broad negative ke sab words any order, phrase ke contiguous same order, exact mein poori query same. Close variants/singular/plural automatic nahi. Punctuation, special symbols aur actual platform eligibility yahan fully model nahi hoti.','Simplified literal-word exercise: broad requires all words in any order; phrase requires a contiguous phrase; exact requires the entire query. Close variants/singular/plural are not automatic. Punctuation, special symbols and platform eligibility are not fully modelled.')}</p><div class="form-grid"><label class="field">${U('Negative ke words · brackets/quotes ke baghair','Negative words · without brackets/quotes')}<input id="negative-text" maxlength="200" value="${esc(n.text)}"></label><label class="field">Match<select id="negative-match">${['broad','phrase','exact'].map(x=>`<option ${x===n.match?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Scope<select id="negative-scope">${[['group','nonbrand / main only'],['campaign','nonbrand campaign'],['account','All fixture campaigns']].map(([v,l])=>`<option value="${v}" ${v===n.scope?'selected':''}>${l}</option>`).join('')}</select></label></div><div id="negative-result">${negativeResult()}</div><p>${U('Scope context: nonbrand/main current ad group hai; nonbrand/other doosra group; brand/main separate campaign. Actual account-level exclusions ki availability/scope account mein verify karo.','Scope context: nonbrand/main is the current group; nonbrand/other is another group; brand/main is a separate campaign. Verify actual account-level exclusion scope and availability in the account.')}</p>${sourceLinks(['negative'])}</section><section class="card" style="margin-top:22px"><h2>${U('03 · Search term par faisla','03 · Decide on a search term')}</h2><p>${U('Keyword aur actual query alag hain. Visible terms report complete search log nahi. Cost, intent, sample maturity aur qualified results dekh kar decision lo.','Keywords and actual queries differ. Visible search terms are not a complete search log. Consider intent, cost, maturity and qualified results.')}</p><div style="overflow:auto"><table class="data-table"><thead><tr><th>Fictional query</th><th>Clicks / spend / outcomes</th><th>${U('Decision','Decision')}</th></tr></thead><tbody>${studioQueries().map((q,i)=>`<tr><td>${esc(q.term)}</td><td>${q.clicks} / ${money(q.cost)} / ${q.out}</td><td><select data-studio-query="${i}" aria-label="Query decision ${i+1}"><option value="">${U('Choose karo','Choose')}</option>${['keep','block','investigate'].map(v=>`<option value="${v}" ${r.answers[i]===v?'selected':''}>${v}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div><button class="btn" id="studio-query-check" style="margin-top:20px">${U('Decisions check karo','Check decisions')}</button><div id="studio-query-feedback" aria-live="polite"></div><div class="action-row"><button class="btn light" id="keyword-export">${U('Keyword plan download','Download keyword plan')}</button></div></section>`;}
function bindStudio(){$('#studio-business').onchange=e=>{state.business=e.target.value;save();rsaRotation=0;render();};$$('[data-studio-tab]').forEach(b=>b.onclick=()=>{studioTab=b.dataset.studioTab;render();});const r=studioRecord();const changed=()=>{save();$('#rsa-save').textContent=storageOK?U('Draft saved; edits ke baad review dobara karo.','Draft saved; review again after edits.'):U('Storage unavailable; draft download karo.','Storage unavailable; download the draft.');$('#rsa-feedback').innerHTML='';$('#rsa-preview').innerHTML=rsaPreview();};$$('[data-rsa-text]').forEach(el=>el.oninput=()=>{const [key,i]=el.dataset.rsaText.split('/');r[key][i].text=el.value.slice(0,1000);const limit=key==='headlines'?30:90,count=$('#rsa-count-'+key+'-'+i);count.textContent=rsaLength(el.value)+'/'+limit;count.style.color=rsaLength(el.value)>limit?'#a14c3e':'';changed();});$$('[data-rsa-pin]').forEach(el=>el.onchange=()=>{const [key,i]=el.dataset.rsaPin.split('/');r[key][i].pin=+el.value;changed();});$$('[data-rsa-path]').forEach(el=>el.oninput=()=>{const i=+el.dataset.rsaPath;r.paths[i]=el.value.slice(0,100);$('#rsa-path-count-'+i).textContent=rsaLength(el.value)+'/15';changed();});const url=$('#rsa-url');if(url)url.oninput=()=>{r.url=url.value.slice(0,2000);changed();};const review=$('#rsa-review');if(review)review.onclick=()=>{const v=reviewRSA(r);$('#rsa-feedback').innerHTML=`<div class="feedback ${v.errors.length?'error':''}" style="margin-top:20px"><b>${v.errors.length?U('Format issues resolve karo','Resolve format issues'):U('Basic format checks pass','Basic format checks pass')}</b>${v.errors.map(x=>`<p>${esc(x)}</p>`).join('')}${v.warnings.map(x=>`<p>↳ ${esc(x)}</p>`).join('')}<p>${U('Truthfulness, page fit, trademark/policy aur actual Google validation manually review karo. Ye Ad Strength score, policy approval ya performance prediction nahi.','Review truthfulness, page fit, trademark/policy and Google validation separately. This is not an Ad Strength score, policy approval or performance prediction.')}</p></div>`;};const rotate=$('#rsa-rotate');if(rotate)rotate.onclick=()=>{rsaRotation++;$('#rsa-preview').innerHTML=rsaPreview();};const expanded=$('#rsa-expanded');if(expanded)expanded.onchange=e=>{rsaExpanded=e.target.checked;$('#rsa-preview').innerHTML=rsaPreview();};const ex=$('#rsa-export');if(ex)ex.onclick=()=>download('ads-asaan-'+state.business+'-full-rsa.json',{simulation:true,business:biz().name[1],headlines:r.headlines,descriptions:r.descriptions,paths:r.paths,finalURL:r.url,review:reviewRSA(r),notice:'Educational draft, not an uploaded or approved ad.'});$$('[data-research]').forEach(el=>el.oninput=()=>{r.research[el.dataset.research]=el.value.slice(0,5000);save();$('#keyword-syntax').innerHTML=syntaxResult();});for(const [id,key]of [['negative-text','text'],['negative-match','match'],['negative-scope','scope']]){const el=$('#'+id);if(el)el[key==='text'?'oninput':'onchange']=()=>{r.negative[key]=el.value;save();$('#negative-result').innerHTML=negativeResult();};}$$('[data-studio-query]').forEach(el=>el.onchange=()=>{if(el.value)r.answers[el.dataset.studioQuery]=el.value;else delete r.answers[el.dataset.studioQuery];save();$('#studio-query-feedback').innerHTML='';});const check=$('#studio-query-check');if(check)check.onclick=()=>{$('#studio-query-feedback').innerHTML=`<h3 style="margin-top:22px">${studioQueryScore()}/8 ${U('case decisions match huay','case decisions matched')}</h3>${studioQueries().map((q,i)=>`<div class="feedback ${r.answers[i]===q.answer?'':'error'}"><b>${esc(q.term)} · ${q.answer}</b><p>${esc(t(q.why))}</p></div>`).join('')}`;};const ke=$('#keyword-export');if(ke)ke.onclick=()=>download('ads-asaan-'+state.business+'-keyword-plan.json',{simulation:true,business:biz().name[1],research:r.research,syntax:keywordSyntax(r.research.keywords||''),negativeExample:r.negative,fixtureConflicts:negativeFixtures().filter(f=>f.useful&&negativeImpact(f,r.negative)),queryDecisions:r.answers,queryScore:studioQueryScore(),notice:'Fictional planning exercise; no live volumes, auction predictions or account changes.'});}
